import React, { useState } from 'react';
import API from '../api/axiosClient';
import { useMutation } from '@tanstack/react-query';
import { FaCreditCard, FaCashRegister, FaCheckCircle, FaEnvelope } from 'react-icons/fa';

export default function WorkerDashboard({ orgId, machineId }) {
    const [rfidUid, setRfidUid] = useState('');
    const [customerEmail, setCustomerEmail] = useState('');
    const [chargeAmount, setChargeAmount] = useState('');
    const [feedback, setFeedback] = useState('');

    // Assign Card Mutation (Using Email)
    const assignMutation = useMutation({
        mutationFn: async (data) => await API.post(`/cards/${orgId}/assign-card`, data),
        onSuccess: (res) => {
            setFeedback(res.data.message);
            setCustomerEmail('');
            setRfidUid('');
        },
        onError: (err) => setFeedback(err.response?.data?.error || 'Failed to assign card')
    });

    // Queue Charge Mutation
    const chargeMutation = useMutation({
        mutationFn: async (data) => await API.post(`/worker/${orgId}/charge`, data),
        onSuccess: (res) => setFeedback(`Queued for ${res.data.customerName}: $${res.data.amount}. Tap card on terminal!`),
        onError: (err) => setFeedback(err.response?.data?.error || 'Failed to queue charge')
    });

    return (
        <div className="space-y-8">
            <h1 className="text-3xl font-bold flex items-center gap-2">
                <FaCashRegister className="text-indigo-400" /> Worker Terminal Dashboard
            </h1>

            {feedback && (
                <div className="p-4 bg-indigo-950 border border-indigo-700/50 rounded-xl text-indigo-200 shadow-lg">
                    {feedback}
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Card Assignment Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl">
                    <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <FaCreditCard className="text-indigo-400" /> Link RFID Card to User
                    </h2>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1">
                                <FaEnvelope /> Customer Email
                            </label>
                            <input 
                                type="email" 
                                placeholder="customer@example.com" 
                                value={customerEmail}
                                onChange={(e) => setCustomerEmail(e.target.value)}
                                className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm text-gray-400 mb-1 flex items-center gap-1">
                                <FaCreditCard /> RFID Card UID
                            </label>
                            <input 
                                type="text" 
                                placeholder="e.g., A4B2C103" 
                                value={rfidUid}
                                onChange={(e) => setRfidUid(e.target.value)}
                                className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                            />
                        </div>
                        <button 
                            onClick={() => assignMutation.mutate({ email: customerEmail, rfidUid })}
                            className="w-full bg-indigo-600 hover:bg-indigo-500 p-3 rounded-lg font-semibold transition"
                        >
                            Link Card
                        </button>
                    </div>
                </div>

                {/* Charge Terminal Card */}
                <div className="bg-gray-800 p-6 rounded-xl border border-gray-700 shadow-xl">
                    <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                        <FaCheckCircle className="text-emerald-400" /> Process Purchase
                    </h2>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Customer RFID UID</label>
                            <input 
                                type="text" 
                                placeholder="Scan or type UID" 
                                value={rfidUid}
                                onChange={(e) => setRfidUid(e.target.value)}
                                className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                            />
                        </div>
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Purchase Amount ($)</label>
                            <input 
                                type="number" 
                                placeholder="15.00" 
                                value={chargeAmount}
                                onChange={(e) => setChargeAmount(e.target.value)}
                                className="w-full p-3 bg-gray-900 border border-gray-700 rounded-lg focus:outline-none focus:border-indigo-500 text-white"
                            />
                        </div>
                        <button 
                            onClick={() => chargeMutation.mutate({ machineId, rfidUid, amount: parseFloat(chargeAmount) })}
                            className="w-full bg-emerald-600 hover:bg-emerald-500 p-3 rounded-lg font-semibold transition"
                        >
                            Queue Charge for Terminal
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}
